+      for (const в of document.body.children){
+        if (в === п || /^(SCRIPT|STYLE)$/.test(в.tagName)) continue;
+        фон.push([в, в.getAttribute('inert')]); в.setAttribute('inert', '');
+      }
+      кнопка.focus(); return;
+    }
     if (!п.hidden && (е.target === п || е.target === і || е.target.closest('#перегляд button'))){
